function shortestPath(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  if (grid[0][0] === 1 || grid[rows - 1][cols - 1] === 1) return -1;

  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const visited = new Set(['0,0']);
  const queue = [[0, 0, 0]];                // [row, col, distance]
  let head = 0;                             // index of the next item to take (cheap dequeue)

  while (head < queue.length) {
    const [row, col, distance] = queue[head];
    head += 1;
    if (row === rows - 1 && col === cols - 1) return distance;
    for (const [dRow, dCol] of directions) {
      const nextRow = row + dRow;
      const nextCol = col + dCol;
      const key = nextRow + ',' + nextCol;
      if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) continue;
      if (grid[nextRow][nextCol] === 1 || visited.has(key)) continue;
      visited.add(key);                     // mark when you ENQUEUE, not when you dequeue
      queue.push([nextRow, nextCol, distance + 1]);
    }
  }
  return -1;
}
